/*
 * The music bank's only translation unit.
 * See MusicBank.h for what ships and why the 4 MB build answers one track.
 *
 * THE ASSETS
 *
 * `src/assets/music/MusE1M1.inc` is generated by `tools/mus2tracks.py` from
 * `tools/DOOM1.WAD`'s `D_E1M1` lump and committed; `MusE1M2.inc` ..
 * `MusE1M9.inc` are the same tool run on `D_E1M2` .. `D_E1M9`. Each defines
 * the note arrays and the four (or three) `MusicTrack` structs in
 * `pixelroot32::audio`; including it here (and nowhere else) keeps one copy in
 * flash. The includes are `const`, so they are .rodata, not .bss.
 *
 * WHY THE SIXTEEN-MEGABYTE GATE DOES NOT TOUCH THE 4 MB IMAGE
 *
 * The nine level themes need 244,016 B of note arrays, which does not fit the
 * 4 MB board's 57,847 B of flash headroom. `DOOM_FULL_PROFILE` is the native
 * build's gate (it is the only environment that defines it), so the eight
 * extra includes sit inside `#if defined(DOOM_FULL_PROFILE)`: a build without
 * the gate never sees them and links exactly the table it linked before.
 *
 * The generated files are the source of truth for tempo and pitch. This file
 * only answers the id lookup; it does not reshape the data.
 */
#include "doomc/MusicBank.h"

#include <pixelroot32/apu/AudioMusicTypes.h>

#include "sounds.h"

#include "assets/music/MusE1M1.inc"

#if defined(DOOM_FULL_PROFILE)
#include "assets/music/MusE1M2.inc"
#include "assets/music/MusE1M3.inc"
#include "assets/music/MusE1M4.inc"
#include "assets/music/MusE1M5.inc"
#include "assets/music/MusE1M6.inc"
#include "assets/music/MusE1M7.inc"
#include "assets/music/MusE1M8.inc"
#include "assets/music/MusE1M9.inc"
#endif

namespace doom {
namespace doomc {

const pixelroot32::audio::MusicTrack* musicBankTrack(int music_id) {
#if defined(DOOM_FULL_PROFILE)
    // Native is the full target: each level id answers its own theme, so a
    // level change starts that level's music (`S_Start` computes
    // mus_e1m1 + (episode-1)*9 + map-1). Ids outside the nine stay nullptr --
    // the dummy row, the intermission, the title and past NUMMUSIC -- so
    // `S_ChangeMusic` leaves those quiet instead of holding a request that can
    // never play.
    switch (music_id) {
        case mus_e1m1: return &pixelroot32::audio::kMusE1M1;
        case mus_e1m2: return &pixelroot32::audio::kMusE1M2;
        case mus_e1m3: return &pixelroot32::audio::kMusE1M3;
        case mus_e1m4: return &pixelroot32::audio::kMusE1M4;
        case mus_e1m5: return &pixelroot32::audio::kMusE1M5;
        case mus_e1m6: return &pixelroot32::audio::kMusE1M6;
        case mus_e1m7: return &pixelroot32::audio::kMusE1M7;
        case mus_e1m8: return &pixelroot32::audio::kMusE1M8;
        case mus_e1m9: return &pixelroot32::audio::kMusE1M9;
        default: return nullptr;
    }
#else
    // The 4 MB build has room for one track (34,320 B of the 57,847 B the app
    // has free), so every level theme resolves to E1M1's. A level change asks
    // for its own id and gets the same asset back, which restarts it. The
    // alternative would be a silent level.
    //
    // The other eight themes live behind DOOM_FULL_PROFILE: the bank is the
    // one place that decision lives, so the gate replaces this lookup and
    // nothing else.
    if (music_id >= mus_e1m1 && music_id <= mus_e1m9) {
        return &pixelroot32::audio::kMusE1M1;
    }
    return nullptr;
#endif
}

}  // namespace doomc
}  // namespace doom
